{
  "name": "opencode-token-tracker-tui",
  "version": "2.0.2",
  "description": "Token usage and cost tracking for OpenCode 2 with CLI stats and a compact sidebar summary",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui/index.d.ts",
      "default": "./dist/tui/index.js"
    }
  },
  "type": "module",
  "bin": {
    "opencode-tokens": "dist/bin/opencode-tokens.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "tsc && node --test dist/test/*.test.js",
    "prepublishOnly": "npm run build",
    "release:check": "node scripts/release.js check",
    "release:prepare": "node scripts/release.js prepare",
    "release:tag": "node scripts/release.js tag",
    "publish": "node scripts/publish.js",
    "publish:bump": "node scripts/publish.js bump",
    "publish:dry": "node scripts/publish.js --dry-run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "sidebar",
    "token",
    "usage",
    "cost",
    "tracking",
    "ai",
    "llm",
    "claude",
    "gpt",
    "anthropic",
    "openai"
  ],
  "author": "EightDoor",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/EightDoor/opencode-token-tracker.git"
  },
  "bugs": {
    "url": "https://github.com/EightDoor/opencode-token-tracker/issues"
  },
  "homepage": "https://github.com/EightDoor/opencode-token-tracker#readme",
  "dependencies": {
    "@opencode/plugin": "^2.0.18"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opentui/core": "0.5.12",
    "@opentui/solid": "0.5.12",
    "@types/node": "^20.0.0",
    "solid-js": "1.9.12",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist/index.js",
    "dist/index.d.ts",
    "dist/lib",
    "dist/bin",
    "dist/tui",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20.0.0"
  }
}
